   147  bool RawPacket::reallocateData(size_t newBufferLength)
   148  {
   149          if ((int)newBufferLength == m_RawDataLen)
   150                  return true;
   151
   152          if ((int)newBufferLength < m_RawDataLen)
   153          {
   154                  LOG_ERROR("Cannot reallocate raw packet to a smaller size. Current data length: %d; requested length: %d", m_RawDataLen, (int)newBufferLength);
   155                  return false;
   156          }
   157
   158          uint8_t* newBuffer = new uint8_t[newBufferLength];
   159          memset(newBuffer, 0, newBufferLength);
   160          memcpy(newBuffer, m_RawData, m_RawDataLen);
   161          if (m_DeleteRawDataAtDestructor)
   162                  delete [] m_RawData;
   163
   164          m_DeleteRawDataAtDestructor = true;
   165          m_RawData = newBuffer;
   166
   167          return true;
   168  }
