   170  bool RawPacket::removeData(int atIndex, size_t numOfBytesToRemove)
   171  {
   172          if ((atIndex + (int)numOfBytesToRemove) > m_RawDataLen)
   173          {
   174                  LOG_ERROR("Remove section is out of raw packet bound");
   175                  return false;
   176          }
   177
   178          int index = atIndex;
   179          while (index < (m_RawDataLen - (int)numOfBytesToRemove))
   180          {
   181                  m_RawData[index] = m_RawData[index+numOfBytesToRemove];
   182                  index++;
   183          }
   184
   185          m_RawDataLen -= numOfBytesToRemove;
   186          m_FrameLength = m_RawDataLen;
   187          return true;
   188  }
